import socket,struct,json,pathlib,time
def execute(listener,host,port):
    import threading
    client,_=listener.accept()
    with client:
        client.settimeout(2)
        with socket.create_connection((host,port),timeout=2) as upstream:
            errors=[]
            def forward(source,target):
                try:
                    while True:
                        data=source.recv(4096)
                        if not data:target.shutdown(socket.SHUT_WR);break
                        target.sendall(data)
                except OSError as exc:
                    errors.append(exc)
                    for conn in (source,target):
                        try:conn.shutdown(socket.SHUT_RDWR)
                        except OSError:pass
            thread=threading.Thread(target=forward,args=(client,upstream));thread.start()
            try:forward(upstream,client)
            finally:thread.join(3)
            if thread.is_alive():raise TimeoutError('relay worker did not stop')
            if errors:raise errors[0]
