def execute(listener,routes):
    import http.client,urllib.parse
    conn,_=listener.accept()
    with conn:
        conn.settimeout(2);request=b''
        while b'\r\n\r\n' not in request:
            data=conn.recv(4096)
            if not data:raise EOFError('short headers')
            request+=data
            if len(request)>16384:raise ValueError('header limit')
        head,extra=request.split(b'\r\n\r\n',1);lines=head.decode('ascii').split('\r\n');method,target,version=lines[0].split(' ')
        if method!='GET' or version!='HTTP/1.1' or not target.startswith('/') or target.startswith('//') or extra:raise ValueError('unsupported request')
        for line in lines[1:]:
            k,v=line.split(':',1)
            if k.lower()=='transfer-encoding' or k.lower()=='content-length' and v.strip()!='0':raise ValueError('request body unsupported')
        path=urllib.parse.urlsplit(target).path
        matched=[prefix for prefix in routes if prefix=='/' or path==prefix or path.startswith(prefix.rstrip('/')+'/')]
        status=404;body=b'not found'
        if matched:
            selected=max(matched,key=len);host,port=routes[selected];upstream=http.client.HTTPConnection(host,port,timeout=2)
            try:upstream.request('GET',target);res=upstream.getresponse();status=res.status;body=res.read()
            finally:upstream.close()
        conn.sendall(('HTTP/1.1 '+str(status)+' Result\r\nContent-Length: '+str(len(body))+'\r\nConnection: close\r\n\r\n').encode()+body)
